        Button("Regenerate") { conversation.regenerate() }
            .buttonStyle(.monarch(.ghost))
            .disabled(conversation.isBusy || conversation.messages.isEmpty)
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme

private struct EchoTransport: MonarchAiTransport {
    func stream(_ request: MonarchAiTransportRequest) -> MonarchAiEventStream {
        MonarchAiEventStream { continuation in
            continuation.yield(.textDelta("You asked: “" + (request.messages.last?.text ?? "") + "”. This reply is streamed word by word from a mock transport."))
            continuation.yield(.done())
            continuation.finish()
        }
    }
}

@State private var conversation = MonarchAiConversation(
    transport: EchoTransport(),
    initialMessages: [
        MonarchAiConversationMessage(id: {{messages.0.id}}, role: {{messages.0.role|case}}, parts: [.text(MonarchAiTextPart(text: {{messages.0.text}}))], createdAt: {{messages.0.createdAt}}),
        MonarchAiConversationMessage(id: {{messages.1.id}}, role: {{messages.1.role|case}}, parts: [.text(MonarchAiTextPart(text: {{messages.1.text}}))], agent: MonarchAiAgentRef(name: {{messages.1.agent}}), createdAt: {{messages.1.createdAt}}),
    ]
)
@State private var prompt = ""

